uint8_t cti_tilt05_sanitise_data_rate(uint8_t data_rate_Hz) {
	if (data_rate_Hz <= 1)
		return 1;
	else if (data_rate_Hz <= 2)
		return 2;
	else if (data_rate_Hz <= 5)
		return 5;
	else if (data_rate_Hz <= 10)
		return 10;
	else if (data_rate_Hz <= 20)
		return 20;
	else if (data_rate_Hz <= 25)
		return 25;
	else if (data_rate_Hz <= 40)
		return 40;
	else if (data_rate_Hz <= 50)
		return 50;
	else if (data_rate_Hz <= 100)
		return 100;
	// Default to 1 (shouldn't ever reach this case)
	else return 1;
}
uint8_t cti_tilt05_sanitise_accelerometer_range(uint8_t acc_range) {
	if (acc_range <= 2)
		return 2;
	else if (acc_range <= 4)
		return 4;
	else if (acc_range <= 8)
		return 8;
	return 2;
}

